// Generates public/<slug>/index.html (one responsive form per brand) from the files in
// widgets/newsletter-signup-embed (itself generated by that widget's build.mjs), so the widget
// stays the single source of truth. The public slugs keep their pre-merge names so existing
// iframe URLs don't change. Run: npm run build
import { readFileSync, writeFileSync, copyFileSync, mkdirSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const widget = join(here, '..', '..', 'widgets', 'newsletter-signup-embed');
const out = join(here, 'public');

const PREFIX = 'vpm-nls';
const FORMS = [
  { slug: 'morning-monitor-signup', brand: 'morning-monitor' },
  { slug: 'virginia-home-grown-signup', brand: 'virginia-home-grown' },
  { slug: 'weekly-update-signup', brand: 'weekly-update' },
];

// Iframe-only additions: transparent page, room for the card shadow, and a resizer that
// reports the content height to the parent (the host listens for 'vpm-embed-resize').
const HOSTED_CSS = `<style>
  html, body { background: transparent; }
  body { padding: 8px 8px 28px; }
</style>`;
const RESIZER = `<script>
(function () {
  var last = 0;
  function send() {
    var h = document.documentElement.getBoundingClientRect().height;
    h = Math.ceil(h);
    if (h === last) return;
    last = h;
    parent.postMessage({ type: 'vpm-embed-resize', height: h }, '*');
  }
  if ('ResizeObserver' in window) new ResizeObserver(send).observe(document.body);
  window.addEventListener('load', send);
  window.addEventListener('resize', send);
  send();
})();
</script>`;

rmSync(out, { recursive: true, force: true });
mkdirSync(out, { recursive: true });
copyFileSync(join(here, '_headers'), join(out, '_headers'));

for (const { slug, brand } of FORMS) {
  // Head (fonts + CSS) from the brand preview; the block itself from the ACF HTML file, so the
  // iframe carries exactly what gets pasted into the CMS.
  const preview = readFileSync(join(widget, brand, 'preview.html'), 'utf8');
  const html = readFileSync(join(widget, brand, 'html.html'), 'utf8');
  const js = readFileSync(join(widget, brand, 'js.js'), 'utf8');
  const head = preview.slice(0, preview.indexOf('<body>'));
  const start = html.indexOf(`<div class="${PREFIX} `);
  const end = html.indexOf('\n<!--', start);
  if (!head.includes('</head>') || start < 0 || end < 0) throw new Error(`${slug}: unexpected source shape`);

  const page = `${head.replace('</head>', `${HOSTED_CSS}\n</head>`)}<body>
${html.slice(start, end).trim()}
<script>
${js}</script>
${RESIZER}
</body>
</html>
`;
  mkdirSync(join(out, slug), { recursive: true });
  writeFileSync(join(out, slug, 'index.html'), page);
  console.log(`${slug}/index.html`);
}

// Embed cheat sheet at the site root.
const rows = FORMS.map(({ slug }) => `${slug}/`);
const snippet = (p) => `&lt;iframe src="https://SIGNUP-HOST/${p}" title="Newsletter signup" loading="lazy" style="width:100%;border:0;height:230px"&gt;&lt;/iframe&gt;`;
writeFileSync(join(out, 'index.html'), `<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex"><title>VPM signup forms (hosted)</title>
<style>body{font:16px/1.5 system-ui,sans-serif;max-width:52rem;margin:2rem auto;padding:0 1rem;color:#101820}code,pre{font-size:13px;background:#f2f4f5;padding:2px 4px;overflow-x:auto}pre{padding:12px;display:block}li{margin:.75rem 0}</style></head>
<body><h1>VPM signup forms (hosted)</h1>
<p>Iframe embeds. Replace <code>SIGNUP-HOST</code> with this site's domain. Add the resizer once per host page (see README).</p>
<ul>${rows.map((p) => `<li><a href="${p}">${p}</a><pre>${snippet(p)}</pre></li>`).join('')}</ul></body></html>
`);
